INSERT INTO public.listening_lessons (title, level, description, content) VALUES ('Public Speaking', 'B2', 'Techniques for delivering powerful presentations and managing Q&A sessions.', '{"part1": {"image_url": "https://images.unsplash.com/photo-1542296332-2e4473faf563?auto=format&fit=crop&q=80&w=800", "options": [{"script": "A scene depicting public speaking."}, {"script": "Working in an office."}, {"script": "Waiting at the station."}], "correct_index": 0}, "part2": [{"question_script": "Topic of public speaking?", "options": [{"script": "About public speaking"}, {"script": "About cooking"}, {"script": "About weather"}], "correct_index": 0}, {"question_script": "When to talk about it?", "options": [{"script": "Raining"}, {"script": "Professional/travel"}, {"script": "Night"}], "correct_index": 1}, {"question_script": "Is it difficult?", "options": [{"script": "Need practice"}, {"script": "Sleeping"}, {"script": "Monday"}], "correct_index": 0}], "part3": {"dialogue": [{"speaker": "A", "text": "Learning public speaking."}, {"speaker": "B", "text": "Important part."}], "questions": [{"enunciado": "Interested in?", "options": ["Public Speaking", "Other", "Nothing"], "correct_index": 0}, {"enunciado": "Description?", "options": ["Boring", "Important", "Unnecessary"], "correct_index": 1}, {"enunciado": "Next?", "options": ["Example", "Gift", "Ticket"], "correct_index": 0}]}, "part4": {"script": "Covered public speaking.", "questions": [{"enunciado": "Focus?", "options": ["Sports", "Public Speaking", "Movies"], "correct_index": 1}, {"enunciado": "Why crucial?", "options": ["Communication", "Sleep", "Food"], "correct_index": 0}, {"enunciado": "Advice?", "options": ["Review", "Forget", "Sleep"], "correct_index": 0}]}}');
